async () => { /* H helpers for this script: globals, runtime state, the open board's test state, a toast spy, a phone call to a contact, and a choice picker that continues until a choice matching rx is on screen */
  const t = window.__test;
  window.__toasts = []; const orig = window.gameAlert; window.gameAlert = (...a) => { window.__toasts.push(a); return orig ? orig(...a) : undefined; };
  window.__ded = {
    g: () => window.gameState.globalVariables,
    rt: () => window.deductionRuntime && window.deductionRuntime.getState(),
    board: () => { const mg = window.MinigameFramework.currentMinigame; const s = mg && mg.getTestState && mg.getTestState(); return s && s.board && s.board.deduction; },
    toastsMatching: (rx) => (window.__toasts || []).filter(a => new RegExp(rx).test(String(a[0]))),
    pick: async (rx, ms = 15000) => { const end = Date.now() + ms; while (Date.now() < end) { const d = t.minigame.getState() && t.minigame.getState().dialogue; if (d && d.awaitingChoice && (d.choices || []).some(c => new RegExp(rx, 'i').test(c.text))) { const r = await t.minigame.choose(rx); return !(r && r.ok === false); } if (d && d.canContinue) await t.minigame.continue(); await new Promise(r => setTimeout(r, 150)); } return false; },
    call: async (name) => { const r = await t.interactInventory('phone'); if (r && r.ok === false) return false; await new Promise(r => setTimeout(r, 400)); const c = await t.minigame.clickText(name); return !(c && c.ok === false); }
  };
  return !!window.deductionRuntime && typeof window.deductionRuntime.getState === 'function'; }

async () => { /* A0 globals declared and calm: no fact held, no verdict, case open, the three hidden foes invisible and not hostile */ const g = window.__ded.g(); const ids = ['okafor','venn','marsh','ishikawa','delacroix'];
  const foes = ['ded_a_doorman','ded_a_lookout','ded_a_acolyte'];
  const hidden = (id) => { const b = window.npcBehaviorManager && window.npcBehaviorManager.getBehavior(id); return !b || b.visible === false || b.initiallyHidden === true; };
  const calm = (id) => !(window.npcHostileSystem && window.npcHostileSystem.isNPCHostile && window.npcHostileSystem.isNPCHostile(id));
  return g.deduction_closed === false && ids.every(s => g['deduction_verdict_ded_a_' + s] === '' && g['deduction_outcome_ded_a_' + s] === '')
    && Object.keys(g).filter(k => k.startsWith('se_intel_a_')).every(k => g[k] === false)
    && foes.every(f => hidden(f) && calm(f)); }

async () => { /* A0 Space and E inert with the board open (no movement, no second minigame) */ const t = window.__test; const a = t.getState(); const p0 = { x: a.player.x, y: a.player.y };
  for (const k of [' ', 'e', 'E']) await t.minigame.pressKey(k); await new Promise(r => setTimeout(r, 300));
  const b = t.getState(); return b.activeMinigame && b.activeMinigame.id === 'intel-board' && Math.abs(b.player.x - p0.x) < 0.5 && Math.abs(b.player.y - p0.y) < 0.5; }

async () => { /* HaX opening call: the case and the favour rule, said once */ const ok = await window.__ded.call('HaX'); if (!ok) return false; const t = window.__test; let seen = ''; const end = Date.now() + 15000;
  while (Date.now() < end) { const d = t.minigame.getState() && t.minigame.getState().dialogue; if (d && d.text) seen += ' ' + d.text; if (d && d.awaitingChoice) break; if (d && d.canContinue) await t.minigame.continue(); await new Promise(r => setTimeout(r, 150)); }
  return /Don't do favours for anyone you haven't checked/.test(seen) && !/(only|exactly) (one|two)/i.test(seen) && window.__ded.g().a_briefed === true; }

async () => { /* A1 intern: three wants granted (Marsh, Ishikawa, Delacroix), Q1 free and two costs after their answers: influence -30, wary set */ const g = window.__ded.g();
  return g.se_intel_a_marsh_wants_promotion && g.se_intel_a_ishikawa_wants_codex && g.se_intel_a_delacroix_wants_codex
    && g.ded_a_intern_influence === -30 && g.ded_a_intern_wary === true; }

async () => { /* A2 the coats: Venn's charm, Ishikawa's charm and notebook; nudges for Venn and Ishikawa only (H+C: 2 decided) */ await new Promise(r => setTimeout(r, 500)); const g = window.__ded.g(); const r = window.__ded.rt();
  const n = window.__ded.toastsMatching('You have enough to decide').map(a => String(a[0]));
  return g.se_intel_a_venn_ward_charm && g.se_intel_a_ishikawa_ward_charm && g.se_intel_a_ishikawa_notebook
    && r.state.nudged.slice().sort().join() === 'ded_a_ishikawa,ded_a_venn' && n.length === 2 && n.some(x => /Venn/.test(x)) && n.some(x => /Ishikawa/.test(x)); }

async () => { /* A3 favour done: phone taken from the inventory, all five Marsh cells shown at once, deduction_favour set, the lookout visible and hostile (deferred: the cloakroom is loaded, so the direct path), nudges now Marsh and Okafor (pigeonhole) */ await new Promise(r => setTimeout(r, 800)); const g = window.__ded.g(); const r = window.__ded.rt(); const inv = window.__test.getState().inventory.map(i => i.name);
  const lookout = window.npcHostileSystem && window.npcHostileSystem.isNPCHostile && window.npcHostileSystem.isNPCHostile('ded_a_lookout');
  return g.deduction_favour_ded_a_marsh === true && g.se_intel_a_marsh_burner_sim && g.se_intel_a_marsh_garden && !inv.includes("Marsh's Phone")
    && r.state.favours.includes('ded_a_marsh') && !!lookout
    && r.state.nudged.includes('ded_a_marsh') && r.state.nudged.includes('ded_a_okafor') && r.decidable.ded_a_delacroix === false; }

async () => { /* A3 marks: Okafor Cultist (keyholder), Marsh Cultist (devotee), through the board's buttons */ const mg = window.MinigameFramework.currentMinigame; const c = (s) => mg.container.querySelector(`[data-suspect="${s}"]`);
  const press = async (s, mark, profile) => { c(s).querySelector(`[data-mark="${mark}"]`).click(); await new Promise(r => setTimeout(r, 150)); if (profile) { const p = c(s).querySelector(`[data-profile="${profile}"]`); if (!p) return false; p.click(); await new Promise(r => setTimeout(r, 150)); } return true; };
  if (!(await press('ded_a_okafor', 'guilty', 'keyholder'))) return false; if (!(await press('ded_a_marsh', 'guilty', 'devotee'))) return false;
  const d = window.__ded.board(); const m = (s) => d.suspects.find(x => x.id === s);
  return m('ded_a_okafor').mark === 'guilty' && m('ded_a_okafor').profile === 'keyholder' && m('ded_a_marsh').profile === 'devotee'; }

