async () => { /* A3 after reload: marks survive, the lookout stays visible and hostile, the favour is recorded */ const r = window.__ded.rt();
  return r.state.marks.ded_a_okafor.mark === 'guilty' && r.state.marks.ded_a_marsh.profile === 'devotee' && r.state.favours.includes('ded_a_marsh')
    && window.__ded.g().deduction_favour_ded_a_marsh === true; }

async () => { /* A4 the camera grants the key; HaX's choice opens (Okafor has no verdict yet); choose Leave her be: a_key_choice follow, no verdict, the 'still needs naming' line */ await new Promise(r => setTimeout(r, 1500)); const g = window.__ded.g(); if (!g.se_intel_a_okafor_brass_key || !g.se_intel_a_okafor_notebook) return false;
  if (!window.MinigameFramework.currentMinigame) { if (!(await window.__ded.call('HaX'))) return false; }
  if (!(await window.__ded.pick('^Leave her be'))) return false; await new Promise(r => setTimeout(r, 500));
  const d = window.__test.minigame.getState().dialogue; const said = d && d.text || '';
  return window.__ded.g().a_key_choice === 'follow' && window.__ded.g().deduction_verdict_ded_a_okafor === '' && /still needs naming/.test(said); }

async () => { /* A5 both right_guilty, written at the verdict (reveal now), 'Right call' toasts, a_ritual_weakened set, no closeHint (three suspects have no verdict), case open */ const g = window.__ded.g(); const r = window.__ded.rt();
  return g.deduction_outcome_ded_a_okafor === 'right_guilty' && g.deduction_outcome_ded_a_marsh === 'right_guilty'
    && r.state.verdicts.ded_a_okafor.kind === 'accuse' && window.__ded.toastsMatching('Right call').length === 2 && g.a_ritual_weakened === true
    && r.state.hinted === false && window.__ded.toastsMatching('Call HaX when you').length === 0 && g.deduction_closed === false && r.state.wrongCount === 0; }

async () => { /* A6 Go in: the case closes, the sanctum is unlocked, and the debrief opens only after the phone closes */ if (!(await window.__ded.pick('^I.m ready to go into the sanctum'))) return false; if (!(await window.__ded.pick('^Go in'))) return false;
  const end = Date.now() + 20000; while (Date.now() < end) { const mg = window.MinigameFramework.currentMinigame; const d = window.__ded.board(); if (d && d.view === 'debrief') break; if (mg && mg.constructor && mg.constructor.name === 'PhoneChatMinigame') { const s = window.__test.minigame.getState().dialogue; if (s && s.canContinue) await window.__test.minigame.continue(); } await new Promise(r => setTimeout(r, 200)); }
  const g = window.__ded.g(); return g.deduction_closed === true && (window.gameState.unlockedRooms || []).includes('a_sanctum') && window.__ded.board() && window.__ded.board().view === 'debrief'; }

async () => { /* A6 debrief: Okafor and Marsh right_guilty with Why lines (the brass key; three marked clues), Venn, Ishikawa and Delacroix Not named (innocent) with theirs; no acolyte; a_case_closed not yet set (close-time actions wait for Finish) */ const d = window.__ded.board().debrief; const c = (s) => d.cards.find(x => x.id === s); const why = (s) => c(s).why.map(w => typeof w === 'string' ? w : JSON.stringify(w)).join(' ');
  const mg = window.MinigameFramework.currentMinigame; const txt = mg.container.textContent;
  return c('ded_a_okafor').outcome === 'right_guilty' && /brass/i.test(why('ded_a_okafor')) && c('ded_a_marsh').outcome === 'right_guilty' && /marked/i.test(why('ded_a_marsh'))
    && ['ded_a_venn','ded_a_ishikawa','ded_a_delacroix'].every(s => c(s).outcome === 'right_clear' && c(s).verdictKind === 'none')
    && /Not named \(innocent\)/.test(txt) && /Courier: no, carries a ward charm/.test(txt) && /Courier: no, was in the lecture hall/.test(txt)
    && d.noBlame === 'allRight' && window.__ded.g().a_case_closed === false; }

async () => { /* A6 Finish: the overlay closes first, then a_case_solved completes, a_case_closed is set, no acolyte revealed (nobody missed), credits not yet rolled */ await new Promise(r => setTimeout(r, 2500)); const g = window.__ded.g(); const r = window.__ded.rt();
  const acolyte = window.npcHostileSystem && window.npcHostileSystem.isNPCHostile && window.npcHostileSystem.isNPCHostile('ded_a_acolyte');
  return !window.__ded.board() && g.a_case_closed === true && r.state.debriefPending === false && !acolyte && r.state.pendingHostiles.length === 0 && g.a_ending === false; }

async () => { /* A7 credits under CASE CLOSED with the ritual line and the follow line; no MISSION COMPLETE in the header, the ticker or the credits */ const end = Date.now() + 20000; while (Date.now() < end && !(window.BondVisualiser && window.BondVisualiser.isOpen())) await new Promise(r => setTimeout(r, 250));
  await new Promise(r => setTimeout(r, 1500)); const root = document.querySelector('.bond-visualiser') || document.body; const txt = root.textContent; const tick = (document.querySelector('.bv-ticker-inner') || {}).textContent || '';
  return /CASE CLOSED/.test(txt) && /began a voice short/.test(txt) && /watched where she went/.test(txt) && !/MISSION COMPLETE/.test(txt) && !/MISSION COMPLETE|WELL PLAYED/.test(tick); }
